<script module lang="ts">
/**
 * Horizontal counterpart of Stack for control rows, meta lines and action groups (`design/components/inline.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/inline.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import {
  attributes,
  joinSlot,
  spacingAttrs,
  type LayoutPatch,
  type SpaceStep,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/layout/layout.module.css'

export type InlineAlign = NonNullable<InlineProps['align']>

export type InlineElement = NonNullable<InlineProps['as']>

export type InlineJustify = NonNullable<InlineProps['justify']>

export interface InlineProps {
  align?: 'stretch' | 'start' | 'center' | 'end' | 'baseline'
  as?: 'div' | 'section' | 'ul' | 'ol' | 'nav'
  children?: Snippet
  gap?: SpaceStep
  justify?: 'start' | 'center' | 'end' | 'between'
  p?: SpaceStep
  patch?: LayoutPatch
  px?: SpaceStep
  py?: SpaceStep
  /**
   * Tag lists and filter rows. Row gap equals column gap.
   */
  wrap?: boolean
}
</script>

<script lang="ts">
let {
  align = 'center',
  as = 'div',
  children,
  gap,
  justify = 'start',
  p,
  patch,
  px,
  py,
  wrap = false,
}: InlineProps = $props()
const joined = joinSlot(undefined, () => ({}))
</script>

{@render joined.start?.()
}{#if joined.shown
  }<svelte:element
    this={as}
    {...attributes(spacingAttrs({ gap, p, px, py, patch }))}
    class={[styles.layout, styles.inline]}
    data-align={align}
    data-justify={justify}
    data-wrap={(wrap) ? '' : undefined}
    data-member="inline"
    >{@render children?.()
  }</svelte:element
>{/if
}{@render joined.end?.()}
